GardenPlantTieCutterMaker.ironStock=18; GardenPlantTieCutterMaker.bronzeStock=14; GardenPlantTieCutterMaker.woodStock=10; GardenPlantTieCutterMaker.leatherStock=8; GardenPlantTieCutterMaker.silverStock=8; GardenPlantTieCutterMaker.goldStock=6; GardenPlantTieCutterMaker.jewelStock=4; GardenPlantTieCutterMaker.pearlStock=4
